<script>(()=>{const toggle=document.querySelector('[data-invoice-toggle]'),fields=document.querySelector('[data-invoice-fields]'),type=document.querySelector('[data-invoice-type]');if(!toggle||!fields)return;const update=()=>{fields.hidden=!toggle.checked;fields.querySelectorAll('input,select').forEach(input=>input.disabled=!toggle.checked);fields.querySelectorAll('[data-company-only]').forEach(label=>{label.hidden=type.value!=='company';const input=label.querySelector('input');if(input){input.disabled=!toggle.checked||type.value!=='company';input.required=toggle.checked&&type.value==='company'}});const recipient=fields.querySelector('[name=invoice_recipient]');if(recipient)recipient.required=toggle.checked&&type.value==='person'};toggle.addEventListener('change',update);type.addEventListener('change',update);update()})();</script>
